package com.dpworld.fms.api;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.provisioning.InMemoryUserDetailsManager; import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity public class SecurityConfig {
 @Bean SecurityFilterChain chain(HttpSecurity h) throws Exception{return h.csrf(c->c.ignoringRequestMatchers("/api/**")).cors(Customizer.withDefaults()).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**","/v3/api-docs/**","/swagger-ui/**","/swagger-ui.html").permitAll().requestMatchers(HttpMethod.GET,"/api/**").hasAnyRole("VIEWER","OPERATOR","DISPATCHER","ADMINISTRATOR").requestMatchers("/api/jobs/**","/api/simulation/**").hasAnyRole("DISPATCHER","ADMINISTRATOR").anyRequest().authenticated()).httpBasic(Customizer.withDefaults()).build();}
 @Bean UserDetailsService users(@Value("${dpwfms.security.local.username:operator}")String username,@Value("${DPWFMS_LOCAL_PASSWORD:change-me-local-only}")String password){var encoder=new BCryptPasswordEncoder();return new InMemoryUserDetailsManager(User.withUsername(username).password(encoder.encode(password)).roles("ADMINISTRATOR","DISPATCHER","OPERATOR","VIEWER").build());}
}
